  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(19, 27, 48, 0.88);
      --panel-border: rgba(142, 168, 255, 0.2);
      --text: #edf2ff;
      --muted: #a5b3d9;
      --accent: #8ab4ff;
      --accent-strong: #bad0ff;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(85, 117, 214, 0.22), transparent 32%),
        linear-gradient(180deg, #10172e 0%, var(--bg) 100%);
      display: flex;
      justify-content: center;
      padding: 48px 20px;
    }

    #app {
      width: min(100%, 880px);
    }

    .page-shell {
      background: var(--panel);
      border: 1px solid var(--panel-border);
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
      border-radius: 24px;
      overflow: hidden;
    }

    .hero {
      padding: 48px 32px 28px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 0.82rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: var(--accent-strong);
      background: rgba(138, 180, 255, 0.12);
      border: 1px solid rgba(138, 180, 255, 0.18);
    }

    h1 {
      margin: 18px 0 10px;
      font-size: clamp(2.1rem, 5vw, 3.4rem);
      line-height: 1.05;
    }

    .intro {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      font-size: 1.03rem;
      line-height: 1.7;
    }

    .faq-list {
      padding: 24px;
      display: grid;
      gap: 16px;
    }

    .example {
      border-radius: 18px;
      border: 1px solid rgba(255, 255, 255, 0.08);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.025));
      overflow: hidden;
      transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
    }

    .example:hover {
      border-color: rgba(138, 180, 255, 0.3);
      transform: translateY(-1px);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.065), rgba(255, 255, 255, 0.03));
    }

    .question {
      width: 100%;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
      padding: 22px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      text-align: left;
      cursor: pointer;
    }

    .question:focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: -2px;
    }

    .question-text {
      font-size: 1.05rem;
      font-weight: 650;
      line-height: 1.5;
    }

    .chevron {
      flex: 0 0 auto;
      width: 18px;
      height: 18px;
      border-right: 2px solid var(--accent-strong);
      border-bottom: 2px solid var(--accent-strong);
      transform: rotate(45deg);
      transition: transform 180ms ease;
      margin-right: 4px;
    }

    .example.open .chevron {
      transform: rotate(-135deg);
      margin-top: 8px;
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .example.open .details {
      grid-template-rows: 1fr;
    }

    .details-inner {
      min-height: 0;
      overflow: hidden;
    }

    .answer {
      padding: 0 24px 24px;
      color: var(--muted);
      line-height: 1.75;
      font-size: 0.98rem;
    }

    .answer p {
      margin: 0;
    }

    @media (max-width: 640px) {
      body {
        padding: 24px 14px;
      }

      .hero {
        padding: 32px 22px 20px;
      }

      .faq-list {
        padding: 16px;
      }

      .question,
      .answer {
        padding-left: 18px;
        padding-right: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed and content, but they can also purr to self-soothe when stressed or recovering. The sound comes from rapid muscle movements around the larynx while they breathe."
      },
      {
        question: "Why do cats sleep so much?",
        answer: "Cats are natural predators that evolved to conserve energy between bursts of activity. It is normal for many cats to sleep 12 to 16 hours a day, with kittens and senior cats often sleeping even more."
      },
      {
        question: "Why do cats knead blankets or laps?",
        answer: "Kneading is a comforting behavior that starts in kittenhood while nursing. Adult cats may keep doing it when they feel safe, cozy, and attached to a person or favorite resting spot."
      },
      {
        question: "What should cats eat?",
        answer: "Cats are obligate carnivores, so they need a diet built around animal protein and nutrients such as taurine. A complete commercial cat food made for their age and health needs is usually the safest everyday choice."
      },
      {
        question: "Why do cats flick their tails?",
        answer: "Tail movement is part of feline body language. A slow swish can mean focus, a quick flick can signal irritation, and an upright tail often shows confidence or friendly interest."
      }
    ];

    function createElement(tag, className, content) {
      const element = document.createElement(tag);
      if (className) {
        element.className = className;
      }
      if (typeof content === "string") {
        element.textContent = content;
      } else if (content instanceof Node) {
        element.appendChild(content);
      } else if (Array.isArray(content)) {
        content.forEach((child) => {
          if (child instanceof Node) {
            element.appendChild(child);
          }
        });
      }
      return element;
    }

    function FAQItem({ question, answer }, index) {
      const section = createElement("div", "example");
      const button = createElement("button", "question");
      const questionText = createElement("span", "question-text", question);
      const chevron = createElement("span", "chevron");
      const details = createElement("div", "details");
      const detailsInner = createElement("div", "details-inner");
      const answerWrap = createElement("div", "answer");
      const answerText = createElement("p", "", answer);
      const panelId = "faq-panel-" + index;

      button.type = "button";
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", panelId);
      details.id = panelId;
      details.hidden = true;

      answerWrap.appendChild(answerText);
      detailsInner.appendChild(answerWrap);
      details.appendChild(detailsInner);
      button.append(questionText, chevron);
      section.append(button, details);

      button.addEventListener("click", () => {
        const isOpen = section.classList.toggle("open");
        button.setAttribute("aria-expanded", String(isOpen));
        details.hidden = !isOpen;
      });

      return section;
    }

    function FAQList(items) {
      const list = createElement("div", "faq-list");
      items.forEach((item, index) => {
        list.appendChild(FAQItem(item, index));
      });
      return list;
    }

    function App() {
      const shell = createElement("main", "page-shell");
      const hero = createElement("header", "hero");
      const eyebrow = createElement("div", "eyebrow", "Cat care and behavior");
      const title = createElement("h1", "", "Frequently asked cat questions");
      const intro = createElement(
        "p",
        "intro",
        "A clean, dark-themed FAQ for curious cat people. Each answer stays tucked away until you open it, keeping the page easy to scan."
      );

      hero.append(eyebrow, title, intro);
      shell.append(hero, FAQList(faqItems));
      return shell;
    }

    document.getElementById("app").appendChild(App());
  </script>
</body>
</html>
